105	func Promote(source, target []Record, strategy, intoBranch string, now time.Time) ([]Record, []Proposal, int, bool) {
106		result := append([]Record(nil), target...)
107		var proposals []Proposal
108		components := newConflictComponents()
109		promoted := 0
110		provenanceChanged := false
111		for _, sf := range source {
112			if sf.Status != StatusActive {
113				continue
114			}
115			sf.Branch = intoBranch
116			if i := IndexOf(result, sf.ID); i >= 0 {
117				merged := UnionAnchors(result[i].Provenance, sf.Provenance)
118				if !slices.Equal(merged, result[i].Provenance) {
119					result[i].Provenance = merged
120					provenanceChanged = true
121				}
122				continue
123			}
124			conflicts := activeConflictIndexes(result, sf)
125			if len(conflicts) == 0 {
126				result = append(result, sf)
127				promoted++
128				continue
129			}
130			switch strategy {
131			case "prefer-target":
132				continue // target wins; drop the source fact
133			case "prefer-source":
134				for _, ci := range conflicts {
135					result[ci].Status = StatusSuperseded
136					result[ci].SupersededBy = sf.ID
137					result[ci].UpdatedAt = now
138				}
139				result = append(result, sf)
140				promoted++
141			default: // keep-both
142				for _, ci := range conflicts {
143					result[ci].RelatedIDs = appendUniqueString(result[ci].RelatedIDs, sf.ID)
144					sf.RelatedIDs = appendUniqueString(sf.RelatedIDs, result[ci].ID)
145					// Same-path facts form a clique. A proposal for every pair is
146					// quadratic and tells a reviewer nothing the spanning edges do
147					// not: the review surface groups proposals into connected
148					// components, so one edge into an already-connected component
149					// is pure duplication. Queue only the edges that actually join
150					// two components, which keeps every conflicting fact reachable
151					// in exactly one review group.
152					if components.connected(sf.ID, result[ci].ID) {
153						continue
154					}
155					components.union(sf.ID, result[ci].ID)
156					proposals = append(proposals, Proposal{
157						Action:      ActionSupersede,
158						CandidateID: sf.ID,
159						TargetID:    result[ci].ID,
160						Confidence:  ConflictConfidence(sf, result[ci]),
161						Branch:      intoBranch,
162					})
163				}
164				result = append(result, sf)
165				promoted++
166			}
167		}
168		return result, proposals, promoted, provenanceChanged || promoted > 0
