// errStaleProposal is returned when a proposal references a fact that no longer
// exists or is no longer active.
var errStaleProposal = errors.New("proposal references a missing or inactive fact")

// removeFactByID returns facts with the record of the given id removed.
func removeFactByID(facts []Record, id string) []Record {
	out := facts[:0:0]
	for _, f := range facts {
		if f.ID != id {
			out = append(out, f)
		}
	}
	return out
}

// ApplyProposal resolves a queued proposal by performing its merge/supersede.
// Merge consolidates the candidate's provenance into the target and removes the
// now-redundant candidate record; supersede marks the target superseded by the
// candidate, which stays active. Both records must be distinct and active.
func ApplyProposal(facts []Record, p Proposal, now time.Time) ([]Record, error) {
	ci := IndexOf(facts, p.CandidateID)
	ti := IndexOf(facts, p.TargetID)
	if ci < 0 || ti < 0 || facts[ci].Status != StatusActive || facts[ti].Status != StatusActive {
		return facts, errStaleProposal
	}
	if ci == ti {
		return facts, errors.New("proposal must reference two distinct facts")
	}
	if p.Action != ActionMerge && p.Action != ActionSupersede {
		return facts, errors.New("proposal action must be merge or supersede")
	}
	facts = clearConflictLink(facts, p.CandidateID, p.TargetID)
	ci = IndexOf(facts, p.CandidateID)
	ti = IndexOf(facts, p.TargetID)
	if p.Action == ActionMerge {
		facts[ti].Provenance = UnionAnchors(facts[ti].Provenance, facts[ci].Provenance)
		facts[ti].UpdatedAt = now
		return removeFactByID(facts, p.CandidateID), nil
	}
	// supersede
	facts[ti].Status = StatusSuperseded
	facts[ti].SupersededBy = facts[ci].ID
	facts[ti].UpdatedAt = now
	return facts, nil
}

// RejectProposal discards a proposal without changing fact status, removing the
// conflict cross-link so the pair is no longer flagged as conflicting.
func RejectProposal(facts []Record, p Proposal) []Record {
	return clearConflictLink(facts, p.CandidateID, p.TargetID)
}

// clearConflictLink removes the RelatedIDs cross-link between two facts.
func clearConflictLink(facts []Record, aID, bID string) []Record {
	for i := range facts {
		switch facts[i].ID {
		case aID:
			facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, bID)
		case bID:
			facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, aID)
		}
	}
	return facts
}

func removeString(values []string, target string) []string {
	out := values[:0:0]
	for _, v := range values {
		if v != target {
			out = append(out, v)
		}
	}
	return out
}

// Promote carries a source branch's active facts into a target set under
// the given strategy, returning the merged set, any conflict proposals queued
// (keep-both), the number of facts promoted, and whether the merged set
// differs from target at all. The last return is the no-op signal callers
// need before skipping a persist: promoted can be 0 while the target still
// changed, because an identical-id fact unions its provenance in without
// counting as promoted.
//
//   - keep-both: copy source facts in; a same-path conflict with an existing
//     active target fact keeps both, cross-links them, and queues a proposal.
//   - prefer-source: source facts win — conflicting target facts are superseded.
//   - prefer-target: target facts win — conflicting source facts are skipped.
//
// Identical facts (same content-derived id) never conflict; their provenance is
// unioned.
//
// Under keep-both every conflicting pair is cross-linked (the ADR-P1-G keep-both
// guarantee), but the queued proposals are a SPANNING set, not one per pair:
// see conflictComponents. Each proposal carries a computed ConflictConfidence
// rather than a placeholder, so nothing reaches a human review queue claiming a
// confidence this package never derived.
func Promote(source, target []Record, strategy, intoBranch string, now time.Time) ([]Record, []Proposal, int, bool) {
	result := append([]Record(nil), target...)
	var proposals []Proposal
	components := newConflictComponents()
	promoted := 0
	provenanceChanged := false
	for _, sf := range source {
		if sf.Status != StatusActive {
			continue
		}
		sf.Branch = intoBranch
		if i := IndexOf(result, sf.ID); i >= 0 {
			merged := UnionAnchors(result[i].Provenance, sf.Provenance)
			if !slices.Equal(merged, result[i].Provenance) {
				result[i].Provenance = merged
				provenanceChanged = true
			}
			continue
		}
		conflicts := activeConflictIndexes(result, sf)
		if len(conflicts) == 0 {
			result = append(result, sf)
			promoted++
			continue
		}
		switch strategy {
		case "prefer-target":
			continue // target wins; drop the source fact
		case "prefer-source":
			for _, ci := range conflicts {
				result[ci].Status = StatusSuperseded
				result[ci].SupersededBy = sf.ID
				result[ci].UpdatedAt = now
			}
			result = append(result, sf)
			promoted++
		default: // keep-both
			for _, ci := range conflicts {
				result[ci].RelatedIDs = appendUniqueString(result[ci].RelatedIDs, sf.ID)
				sf.RelatedIDs = appendUniqueString(sf.RelatedIDs, result[ci].ID)
				// Same-path facts form a clique. A proposal for every pair is
				// quadratic and tells a reviewer nothing the spanning edges do
				// not: the review surface groups proposals into connected
				// components, so one edge into an already-connected component
				// is pure duplication. Queue only the edges that actually join
				// two components, which keeps every conflicting fact reachable
				// in exactly one review group.
				if components.connected(sf.ID, result[ci].ID) {
					continue
				}
				components.union(sf.ID, result[ci].ID)
				proposals = append(proposals, Proposal{
					Action:      ActionSupersede,
					CandidateID: sf.ID,
					TargetID:    result[ci].ID,
					Confidence:  ConflictConfidence(sf, result[ci]),
					Branch:      intoBranch,
				})
			}
			result = append(result, sf)
			promoted++
		}
	}
	return result, proposals, promoted, provenanceChanged || promoted > 0
}

